import { InlineHelp } from "./InlineHelp";
import React, { useCallback, useEffect, useMemo, useState } from "react";
import * as XLSX from "xlsx";
import { Building2, Download, FileText, Landmark, Languages, LogOut, PackagePlus, Plus, RefreshCw, Settings2, ShoppingBag, Wallet } from "lucide-react";
import type { AppUser } from "../types";
import { calculateBankBalance, calculateCompanyProfit, calculateProcurementCosting, calculateWeightedAverageItemCost } from "../companyFinance/model";
import type { CompanyFinanceDatabase, CompanyFinanceEntry, CompanyId, CompanyLanguage, ProcurementCase, ProcurementCost } from "../companyFinance/types";

type Props = { embedded?: boolean; user: AppUser; isArcaAdmin?: boolean; onLogout?: () => void };
type Section = "overview" | "procurement" | "sales" | "finance" | "settings";

const labels = {
  en: {
    overview: "Overview", procurement: "Procurement", sales: "Local sales", finance: "Cash & expenses", settings: "Company setup", invoices: "Invoices", issueInvoice: "Issue invoice", invoiceNumber: "Invoice", invoiceTotal: "Invoice total", taxConfigured: "Tax setting confirmed", invoiceReady: "Set legal name, base currency and tax treatment first.", paymentMethod: "Payment method", cash: "Cash", bankPayment: "Bank", check: "Check", credit: "Credit", checkNumber: "Check number", maturity: "Maturity date", bankAccount: "Bank account", linkedCase: "Linked procurement", linkedInvoice: "Invoice", bankTransfer: "Bank transfer", transferTo: "Transfer to", submitTransfer: "Record transfer", clear: "Cleared", pending: "Pending", openingBalance: "Opening balance", bankBalance: "Calculated balance", addItem: "Add item", sku: "SKU", weight: "Weight per unit (kg)", markup: "Default markup %", noItems: "Add an item to the company catalog in Company setup first.", estimatedCost: "Weighted average landed cost", priceHint: "Suggested selling price", saleFx: "Base currency per 1 sale currency", itemName: "Item name", itemNameTr: "Turkish name", receive: "Record receipt", invoicedRevenue: "Invoiced revenue", costOfGoods: "Cost of goods sold", grossProfit: "Gross profit", otherIncome: "Other income", operatingExpenses: "Operating expenses", netProfit: "Net result", invoiceTax: "Invoice tax", profitBasis: "Accrual view: issued invoices and saved cost snapshots.", incompleteProfit: "Profit report needs complete cost and currency data.",
    refresh: "Reload", export: "Export Excel", loading: "Loading company books…", failed: "The company books could not be loaded.",
    saved: "Saved", conflict: "Another user changed this company book. Reload before continuing.", saveFailed: "Save failed. Your entry is still on this form.",
    setup: "Complete company name, base currency and tax settings before issuing invoices.", empty: "No records yet.", newPurchase: "New procurement case", supplier: "Supplier", number: "Case number", date: "Date", currency: "Currency", description: "Description", quantity: "Quantity", unit: "Unit", unitPrice: "Unit purchase price", received: "Received quantity", rate: "Rate to base currency", create: "Create case", purchaseCases: "Procurement cases", costs: "Case costs", case: "Case", category: "Cost category", amount: "Amount", allocation: "Allocate by", allocationValue: "Purchase value", allocationQuantity: "Quantity", allocationWeight: "Weight", allocationDirect: "Direct to lines", addCost: "Add case cost", costPerUnit: "Landed cost per received unit", incomplete: "Incomplete costing", complete: "Costing ready", party: "Company contact", item: "Product or service", localSales: "Local sales projects", newSale: "New local sale", customer: "Customer", salePrice: "Unit sale price", tax: "Tax rate %", createSale: "Create sale record", companyEntries: "Company receipts and expenses", type: "Entry type", expense: "Company expense", income: "Company income", supplierPayment: "Supplier payment", customerReceipt: "Customer receipt", reference: "Reference", addEntry: "Record entry", bank: "Bank accounts", bankName: "Account name", createBank: "Add account", noCurrency: "Not set", legalName: "Legal name", baseCurrency: "Base currency", taxMode: "Tax mode", exclusive: "Tax added to price", inclusive: "Tax included in price", defaultTax: "Default tax %", saveSettings: "Save settings", language: "Language", arcaCompany: "Company books", tenantInfo: "Your account is assigned to one company. Arcatav customer and proforma data is not part of this workspace.", currencyMissing: "Base currency and a valid exchange rate are required for cost calculation.", exportDescription: "Exports only the selected company's records.", noSupplier: "Add a supplier in the form above first.", signOut: "Sign out", noBank: "No bank accounts added.", noParty: "Create a contact in the company settings before recording a local sale.",
  },
  tr: {
    overview: "Genel Bakış", procurement: "Satın Alma", sales: "Yerel Satış", finance: "Kasa ve Giderler", settings: "Şirket Ayarları", invoices: "Faturalar", issueInvoice: "Fatura düzenle", invoiceNumber: "Fatura", invoiceTotal: "Fatura tutarı", taxConfigured: "Vergi ayarı onaylandı", invoiceReady: "Önce resmî unvanı, temel para birimini ve vergi şeklini ayarlayın.", paymentMethod: "Ödeme yöntemi", cash: "Nakit", bankPayment: "Banka", check: "Çek", credit: "Vadeli", checkNumber: "Çek numarası", maturity: "Vade tarihi", bankAccount: "Banka hesabı", linkedCase: "Bağlı satın alma", linkedInvoice: "Fatura", bankTransfer: "Hesaplar arası transfer", transferTo: "Hedef hesap", submitTransfer: "Transfer kaydet", clear: "Tahsil edildi", pending: "Beklemede", openingBalance: "Açılış bakiyesi", bankBalance: "Hesaplanan bakiye", addItem: "Ürün ekle", sku: "Stok kodu", weight: "Birim ağırlığı (kg)", markup: "Varsayılan kâr marjı %", noItems: "Önce Şirket Ayarları bölümünden ürün ekleyin.", estimatedCost: "Ortalama maliyet", priceHint: "Önerilen satış fiyatı", saleFx: "1 satış para birimi başına temel para birimi", itemName: "Ürün adı", itemNameTr: "Türkçe ürün adı", receive: "Teslimat kaydet", invoicedRevenue: "Faturalanan gelir", costOfGoods: "Satılan malın maliyeti", grossProfit: "Brüt kâr", otherIncome: "Diğer gelir", operatingExpenses: "Faaliyet gideri", netProfit: "Net sonuç", invoiceTax: "Fatura vergisi", profitBasis: "Tahakkuk görünümü: düzenlenen faturalar ve kayıtlı maliyet anlık görüntüleri.", incompleteProfit: "Kâr raporu için maliyet ve kur bilgileri tamamlanmalı.",
    refresh: "Yenile", export: "Excel'e Aktar", loading: "Şirket defteri yükleniyor…", failed: "Şirket defteri yüklenemedi.",
    saved: "Kaydedildi", conflict: "Başka bir kullanıcı bu defteri değiştirdi. Devam etmeden önce yenileyin.", saveFailed: "Kayıt başarısız. Girdi formda duruyor.",
    setup: "Fatura düzenlemeden önce şirket unvanını, temel para birimini ve vergi ayarlarını tamamlayın.", empty: "Henüz kayıt yok.", newPurchase: "Yeni satın alma dosyası", supplier: "Tedarikçi", number: "Dosya numarası", date: "Tarih", currency: "Para Birimi", description: "Açıklama", quantity: "Miktar", unit: "Birim", unitPrice: "Birim alış fiyatı", received: "Teslim alınan miktar", rate: "Temel para birimine kur", create: "Dosya oluştur", purchaseCases: "Satın alma dosyaları", costs: "Dosya giderleri", case: "Dosya", category: "Gider türü", amount: "Tutar", allocation: "Dağıtım yöntemi", allocationValue: "Alış değeri", allocationQuantity: "Miktar", allocationWeight: "Ağırlık", allocationDirect: "Satırlara doğrudan", addCost: "Dosya gideri ekle", costPerUnit: "Teslim alınan birim başına maliyet", incomplete: "Maliyet eksik", complete: "Maliyet hazır", party: "Şirket bağlantısı", item: "Ürün veya hizmet", localSales: "Yerel satış projeleri", newSale: "Yeni yerel satış", customer: "Müşteri", salePrice: "Birim satış fiyatı", tax: "Vergi oranı %", createSale: "Satış kaydı oluştur", companyEntries: "Şirket tahsilat ve giderleri", type: "Kayıt türü", expense: "Şirket gideri", income: "Şirket geliri", supplierPayment: "Tedarikçi ödemesi", customerReceipt: "Müşteri tahsilatı", reference: "Referans", addEntry: "Kayıt ekle", bank: "Banka hesapları", bankName: "Hesap adı", createBank: "Hesap ekle", noCurrency: "Belirtilmedi", legalName: "Resmî unvan", baseCurrency: "Temel para birimi", taxMode: "Vergi türü", exclusive: "Vergi fiyata eklenir", inclusive: "Vergi fiyata dahildir", defaultTax: "Varsayılan vergi %", saveSettings: "Ayarları kaydet", language: "Dil", arcaCompany: "Şirket defterleri", tenantInfo: "Hesabınız yalnızca bir şirkete bağlıdır. Arcatav müşteri ve proforma bilgileri bu alanda bulunmaz.", currencyMissing: "Maliyet için temel para birimi ve geçerli kur gerekir.", exportDescription: "Yalnızca seçilen şirketin kayıtları dışa aktarılır.", noSupplier: "Önce yukarıdaki formdan tedarikçi ekleyin.", signOut: "Çıkış yap", noBank: "Banka hesabı eklenmedi.", noParty: "Yerel satış kaydetmeden önce şirket ayarlarından bir bağlantı oluşturun.",
  },
} as const;

const today = () => new Date().toISOString().slice(0, 10);
const id = (prefix: string) => `${prefix}-${crypto.randomUUID()}`;
const money = (value: number, currency: string) => `${new Intl.NumberFormat(undefined, { maximumFractionDigits: 2 }).format(value)} ${currency || ""}`.trim();
const companyLabel = (companyId: CompanyId) => companyId === "berakem" ? "Berakem" : "Arovin";

export const CompanyFinancePortal: React.FC<Props> = ({ user, isArcaAdmin = false, onLogout, embedded = false }) => {
  const allowedCompany = user.role === "company_finance" ? user.companyId : undefined;
  const [selectedCompany, setSelectedCompany] = useState<CompanyId>(allowedCompany || "berakem");
  const companyId = isArcaAdmin ? selectedCompany : allowedCompany || "berakem";
  const [language, setLanguage] = useState<CompanyLanguage>(() => {
    const saved = localStorage.getItem(`company-finance-language:${user.id}`);
    return companyId === "berakem" && (saved === "tr" || saved === "en") ? saved : user.preferredPortalLanguage === "tr" && companyId === "berakem" ? "tr" : "en";
  });
  const t = labels[language];
  const [section, setSection] = useState<Section>("overview");
  const [data, setData] = useState<CompanyFinanceDatabase | null>(null);
  const [revision, setRevision] = useState("");
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");
  const [notice, setNotice] = useState("");

  const load = useCallback(async () => {
    setLoading(true); setError(""); setNotice("");
    try {
      const query = isArcaAdmin ? `?companyId=${companyId}` : "";
      const response = await fetch(`/api/company-finance${query}`, { credentials: "same-origin", cache: "no-store" });
      const result = await response.json().catch(() => ({}));
      if (!response.ok) throw new Error(result.error || t.failed);
      if (!isArcaAdmin && result.companyId !== allowedCompany) { window.location.reload(); return; }
      setData(result.data); setRevision(result.revision || "");
    } catch (reason: any) { setError(reason?.message || t.failed); setData(null); }
    finally { setLoading(false); }
  }, [allowedCompany, companyId, isArcaAdmin, t.failed]);

  useEffect(() => { void load(); }, [load]);
  useEffect(() => { if (companyId !== "berakem") setLanguage("en"); }, [companyId]);

  const persist = async (next: CompanyFinanceDatabase): Promise<boolean> => {
    if (saving) return false;
    setSaving(true); setError(""); setNotice("");
    try {
      const query = isArcaAdmin ? `?companyId=${companyId}` : "";
      const response = await fetch(`/api/company-finance${query}`, {
        method: "PUT", credentials: "same-origin",
        headers: { "Content-Type": "application/json", "X-Arca-Company-Revision": revision },
        body: JSON.stringify({ data: { ...next, companyId } }),
      });
      const result = await response.json().catch(() => ({}));
      if (response.status === 409) { setRevision(result.revision || revision); throw new Error(t.conflict); }
      if (!response.ok) throw new Error(result.error || t.saveFailed);
      setData(result.data); setRevision(result.revision || ""); setNotice(t.saved);
      window.setTimeout(() => setNotice(""), 2500);
      return true;
    } catch (reason: any) { setError(reason?.message || t.saveFailed); return false; }
    finally { setSaving(false); }
  };

  const costing = useMemo(() => data?.procurementCases.flatMap((record) => calculateProcurementCosting(record, data)) || [], [data]);
  const incompleteCosting = costing.filter((record) => !record.complete).length;
  const totalCases = data?.procurementCases.length || 0;
  const totalSales = data?.localSales.length || 0;

  const exportWorkbook = () => {
    if (!data) return;
    const workbook = XLSX.utils.book_new();
    const append = (rows: Record<string, unknown>[], sheet: string) => XLSX.utils.book_append_sheet(workbook, XLSX.utils.json_to_sheet(rows.length ? rows : [{ Note: t.empty }]), sheet.slice(0, 31));
    append([{ Company: companyLabel(companyId), ExportedAt: new Date().toISOString(), BaseCurrency: data.settings.baseCurrency, Locale: language }], "Company");
    append(data.parties.map((party) => ({ Kind: party.kind, Name: party.name, LegalName: party.legalName || "", TaxId: party.taxId || "", Email: party.email || "", Phone: party.phone || "", Address: party.address || "" })), "Contacts");
    append(data.items.map((item) => ({ SKU: item.sku, Name: item.name, NameTurkish: item.nameTr || "", Unit: item.unit, WeightPerUnitKg: item.weightPerUnitKg || "", TaxRate: item.taxRate ?? "", MarkupPercent: item.defaultMarkupPercent ?? "", Active: item.active ? "Yes" : "No" })), "Items");
    append(data.procurementCases.flatMap((record) => record.lines.map((line) => {
      const cost = costing.find((item) => item.caseId === record.id && item.lineId === line.id);
      return { Case: record.number, Date: record.date, Supplier: data.parties.find((party) => party.id === record.supplierId)?.name || "", Product: line.description, Quantity: line.quantity, Received: line.receivedQuantity, Unit: line.unit, PurchaseUnitPrice: line.unitPrice, Currency: line.currency, LandedCost: cost?.landedCost ?? "", LandedCostPerUnit: cost?.costPerUnit ?? "", CostingComplete: cost?.complete ? "Yes" : "No", CostingIssues: cost?.issues.join("; ") || "" };
    })), "Procurement");
    append(data.procurementCases.flatMap((record) => record.costs.map((cost) => ({ Case: record.number, Date: cost.date, Category: cost.category, Description: cost.description, Amount: cost.amount, Currency: cost.currency, Allocation: cost.allocation }))), "Case Costs");
    append(data.localSales.map((sale) => ({ Number: sale.number, Date: sale.date, Customer: data.parties.find((party) => party.id === sale.customerId)?.name || "", Currency: sale.currency, Status: sale.status, PaymentTerms: sale.paymentTerms || "" })), "Local Sales");
    append(data.invoices.map((invoice) => ({ Number: invoice.number, Date: invoice.issuedAt, DueDate: invoice.dueAt || "", Customer: invoice.customerSnapshot, Currency: invoice.currency, Subtotal: invoice.subtotal, Tax: invoice.taxTotal, Total: invoice.total, Status: invoice.status })), "Invoices");
    append(data.entries.map((entry) => ({ Date: entry.date, Type: entry.type, Description: entry.description, Amount: entry.amount, Currency: entry.currency, Reference: entry.reference || "", PaymentMethod: entry.paymentMethod || "", Check: entry.checkNumber || "", MaturityDate: entry.checkMaturityDate || "" })), "Finance Entries");
    append(data.bankAccounts.map((account) => ({ Account: account.name, Bank: account.bankName || "", Currency: account.currency, OpeningBalance: account.openingBalance, Active: account.active ? "Yes" : "No" })), "Bank Accounts");
    const profit = calculateCompanyProfit(data);
    append([{ Basis: "Accrual view", Currency: profit.currency, InvoicedRevenue: profit.invoicedRevenue, CostOfGoodsSold: profit.costOfGoodsSold, GrossProfit: profit.grossProfit, OtherIncome: profit.otherIncome, OperatingExpenses: profit.operatingExpenses, CustomerRefunds: profit.customerRefunds, NetResult: profit.netProfit, InvoiceTaxSeparate: profit.taxOnInvoices, UncostedInvoiceLines: profit.uncostedInvoiceLines, MissingFxRecords: profit.missingFxRecords }], "Profit Summary");
    append(data.auditEvents.map((event) => ({ At: event.at, Actor: event.actorName, Action: event.action, Entity: event.entityType, RecordId: event.entityId, Reason: event.reason || "" })), "Audit");
    XLSX.writeFile(workbook, `${companyId}-finance-${today()}.xlsx`);
  };

  return <main data-company-embedded={embedded || undefined} className={`${embedded ? "min-h-0" : "min-h-screen"} bg-slate-100 text-slate-800`} dir="ltr">
    <header className="sticky top-0 z-30 border-b border-slate-800 bg-slate-950 px-4 py-3 text-white shadow-lg">
      <div className="mx-auto flex max-w-7xl flex-wrap items-center justify-between gap-3">
        <div className="flex items-center gap-3"><div className="rounded-lg bg-cyan-500/15 p-2 text-cyan-300"><Building2 size={20}/></div><div><b className="text-sm">{isArcaAdmin ? t.arcaCompany : companyLabel(companyId)} Finance</b><p className="text-[10px] text-slate-400">{isArcaAdmin ? t.arcaCompany : t.tenantInfo}</p></div></div>
        <div className="flex items-center gap-2">
          {isArcaAdmin && <select aria-label="Company" value={companyId} onChange={(event) => setSelectedCompany(event.target.value as CompanyId)} className="rounded-lg border border-slate-700 bg-slate-900 px-2 py-1.5 text-xs text-white"><option value="berakem">Berakem</option><option value="arovin">Arovin</option></select>}
          {companyId === "berakem" && <label className="flex items-center gap-1 rounded-lg border border-slate-700 px-2 py-1 text-xs"><Languages size={13}/><select value={language} onChange={(event) => { const next = event.target.value as CompanyLanguage; setLanguage(next); localStorage.setItem(`company-finance-language:${user.id}`, next); }} className="bg-slate-950 text-white"><option value="en">English</option><option value="tr">Türkçe</option></select></label>}
          <button type="button" onClick={() => void load()} className="rounded-lg border border-slate-700 p-2 text-slate-300 hover:bg-slate-800" title={t.refresh}><RefreshCw size={15}/></button>
          <button type="button" onClick={exportWorkbook} disabled={!data} className="flex items-center gap-1 rounded-lg bg-emerald-700 px-3 py-2 text-xs font-bold text-white disabled:opacity-40"><Download size={14}/>{t.export}</button>
          {onLogout && <button type="button" onClick={onLogout} className="rounded-lg bg-rose-700 p-2" title={t.signOut}><LogOut size={15}/></button>}
        </div>
      </div>
    </header>
    <div className={`mx-auto grid max-w-7xl gap-4 p-4 ${embedded ? "" : "lg:grid-cols-[220px_1fr]"}`}>
      {embedded ? <select aria-label="Company finance section" value={section} onChange={event=>setSection(event.target.value as Section)} className="w-full rounded-lg border p-3 sm:max-w-sm">{(["overview", "procurement", "sales", "finance", "settings"] as Section[]).map(key=><option value={key} key={key}>{t[key]}</option>)}</select> : <nav className="flex gap-1 overflow-auto rounded-xl border bg-white p-2 lg:block lg:space-y-1 lg:self-start">{(["overview", "procurement", "sales", "finance", "settings"] as Section[]).map((key) => <button type="button" key={key} onClick={() => setSection(key)} className={`flex shrink-0 items-center gap-2 rounded-lg px-3 py-2 text-left text-xs font-bold lg:w-full ${section === key ? "bg-cyan-700 text-white" : "text-slate-600 hover:bg-slate-100"}`}><span>{key === "overview" ? <Building2 size={15}/> : key === "procurement" ? <PackagePlus size={15}/> : key === "sales" ? <ShoppingBag size={15}/> : key === "finance" ? <Wallet size={15}/> : <Settings2 size={15}/>}</span>{t[key]}</button>)}</nav>}
      <section className="min-w-0 space-y-4">
        {error && <div role="alert" className="flex flex-wrap items-center justify-between gap-2 rounded-lg border border-rose-200 bg-rose-50 p-3 text-xs text-rose-800">{error}{error === t.conflict && <button type="button" onClick={() => void load()} className="rounded bg-rose-700 px-3 py-1.5 font-bold text-white">{t.refresh}</button>}</div>}
        {notice && <p role="status" className="rounded-lg border border-emerald-200 bg-emerald-50 p-2 text-xs text-emerald-800">{notice}</p>}
        {loading && <p className="rounded-xl border bg-white p-8 text-center text-sm text-slate-500">{t.loading}</p>}
        {!loading && !data && <p className="rounded-xl border bg-white p-8 text-center text-sm text-slate-500">{t.failed}</p>}
        {!loading && data && <>
          {(!data.settings.baseCurrency || !data.settings.legalName || !data.settings.taxConfigured) && <div className="rounded-xl border border-amber-200 bg-amber-50 p-3 text-xs text-amber-900">{t.setup}</div>}
          {section === "overview" && <Overview companyId={companyId} data={data} totalCases={totalCases} totalSales={totalSales} incompleteCosting={incompleteCosting} t={t}/>}
          {section === "procurement" && <Procurement data={data} costing={costing} t={t} onSave={persist} saving={saving} user={user}/>}
          {section === "sales" && <Sales data={data} t={t} onSave={persist} saving={saving} user={user}/>}
          {section === "finance" && <Finance data={data} t={t} onSave={persist} saving={saving} user={user}/>}
          {section === "settings" && <Settings data={data} t={t} onSave={persist} saving={saving} language={language}/>}
        </>}
      </section>
    </div>
  </main>;
};

const Overview = ({ companyId, data, totalCases, totalSales, incompleteCosting, t }: { companyId: CompanyId; data: CompanyFinanceDatabase; totalCases: number; totalSales: number; incompleteCosting: number; t: typeof labels.en | typeof labels.tr }) => <>
  {(() => {
    const profit = calculateCompanyProfit(data);
    return <Card title={t.profitBasis} icon={<FileText size={16}/> }><div className="grid gap-2 sm:grid-cols-2 xl:grid-cols-4"><ProfitStat label={t.invoicedRevenue} value={profit.invoicedRevenue} currency={profit.currency}/><ProfitStat label={t.costOfGoods} value={profit.costOfGoodsSold} currency={profit.currency}/><ProfitStat label={t.grossProfit} value={profit.grossProfit} currency={profit.currency}/><ProfitStat label={t.otherIncome} value={profit.otherIncome} currency={profit.currency}/><ProfitStat label={t.operatingExpenses} value={profit.operatingExpenses} currency={profit.currency}/><ProfitStat label={t.netProfit} value={profit.netProfit} currency={profit.currency}/><ProfitStat label={t.invoiceTax} value={profit.taxOnInvoices} currency={profit.currency}/><Stat label={t.incompleteProfit} value={profit.uncostedInvoiceLines + profit.missingFxRecords}/></div><p className="mt-2 text-[10px] text-slate-500">{t.profitBasis} · {profit.currency || t.noCurrency}</p></Card>;
  })()}
  <div className="rounded-2xl bg-gradient-to-r from-slate-950 to-cyan-950 p-5 text-white"><p className="text-xs text-cyan-200">{t.arcaCompany}</p><h1 className="mt-1 text-xl font-black">{companyLabel(companyId)} — Finance workspace</h1><p className="mt-2 max-w-2xl text-xs leading-5 text-slate-300">{t.tenantInfo}</p></div>
  <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">{[[t.purchaseCases, totalCases], [t.localSales, totalSales], [t.costs, data.procurementCases.reduce((sum, item) => sum + item.costs.length, 0)], [t.incomplete, incompleteCosting]].map(([label, value]) => <div key={String(label)} className="rounded-xl border bg-white p-4 shadow-sm"><p className="text-xs text-slate-500">{label}</p><p className="mt-2 text-2xl font-black text-slate-900">{value}</p></div>)}</div>
  <div className="rounded-xl border bg-white p-4"><h2 className="text-sm font-bold">{t.exportDescription}</h2><p className="mt-1 text-xs text-slate-500">{t.setup}</p><div className="mt-4 grid gap-2 sm:grid-cols-3"><Stat label={t.supplier} value={data.parties.filter((item) => item.kind === "supplier").length}/><Stat label={t.customer} value={data.parties.filter((item) => item.kind === "customer").length}/><Stat label={t.bank} value={data.bankAccounts.length}/></div></div>
</>;

const Stat = ({ label, value }: { label: string; value: number }) => <div className="rounded-lg bg-slate-50 p-3 text-xs"><span className="text-slate-500">{label}</span><b className="float-right">{value}</b></div>;
const ProfitStat = ({ label, value, currency }: { label: string; value: number; currency: string }) => <div className="rounded-lg bg-slate-50 p-3 text-xs"><span className="text-slate-500">{label}</span><b className="float-right">{money(value, currency)}</b></div>;
const Card = ({ title, icon, children }: { title: string; icon?: React.ReactNode; children: React.ReactNode }) => <div className="rounded-xl border border-slate-200 bg-white p-4 shadow-sm"><h2 className="mb-3 flex items-center gap-2 text-sm font-bold">{icon}{title}</h2>{children}</div>;
const Field = ({ label, ...props }: React.InputHTMLAttributes<HTMLInputElement> & { label: string }) => <label className="block text-[11px] font-semibold text-slate-600">{label}<input {...props} className={`mt-1 w-full rounded-lg border border-slate-200 bg-white p-2 text-xs text-slate-900 ${props.className || ""}`}/></label>;

function Procurement({ data, costing, t, onSave, saving, user }: { data: CompanyFinanceDatabase; costing: ReturnType<typeof calculateProcurementCosting>; t: typeof labels.en | typeof labels.tr; onSave: (next: CompanyFinanceDatabase) => Promise<boolean>; saving: boolean; user: AppUser }) {
  const [supplierName, setSupplierName] = useState(""); const [caseNumber, setCaseNumber] = useState(""); const [description, setDescription] = useState(""); const [itemId, setItemId] = useState(""); const [date, setDate] = useState(today()); const [currency, setCurrency] = useState(data.settings.baseCurrency || "USD"); const [quantity, setQuantity] = useState(0); const [unit, setUnit] = useState<"unit" | "kg" | "mt">("mt"); const [unitPrice, setUnitPrice] = useState(0); const [received, setReceived] = useState(0); const [rate, setRate] = useState(1);
  const [costCaseId, setCostCaseId] = useState(""); const [costCategory, setCostCategory] = useState(""); const [costDescription, setCostDescription] = useState(""); const [costAmount, setCostAmount] = useState(0); const [costCurrency, setCostCurrency] = useState(data.settings.baseCurrency || "USD"); const [allocation, setAllocation] = useState<ProcurementCost["allocation"]>("value"); const [costRate, setCostRate] = useState(1);
  const supplierOptions = data.parties.filter((party) => party.kind === "supplier");
  const createCase = async (event: React.FormEvent) => {
    event.preventDefault(); if (!supplierName.trim() || !caseNumber.trim() || !itemId || !description.trim() || quantity <= 0 || unitPrice < 0 || received < 0 || received > quantity) return;
    const now = new Date().toISOString();
    const supplier = supplierOptions.find((item) => item.name.trim().toLowerCase() === supplierName.trim().toLowerCase()) || { id: id("supplier"), kind: "supplier" as const, name: supplierName.trim(), createdAt: now };
    const record: ProcurementCase = { id: id("purchase"), number: caseNumber.trim(), supplierId: supplier.id, currency: currency.toUpperCase(), date, status: received >= quantity ? "received" : received > 0 ? "partially_received" : "open", lines: [{ id: id("line"), itemId, description: description.trim(), quantity, unit, unitPrice, currency: currency.toUpperCase(), exchangeRateToBase: currency.toUpperCase() === data.settings.baseCurrency.toUpperCase() ? 1 : rate, receivedQuantity: received }], costs: [], createdAt: now, createdBy: user.id, updatedAt: now };
    if (!await onSave({ ...data, parties: supplierOptions.some((item) => item.id === supplier.id) ? data.parties : [...data.parties, supplier], procurementCases: [record, ...data.procurementCases] })) return;
    setCaseNumber(""); setDescription(""); setQuantity(0); setUnitPrice(0); setReceived(0);
  };
  const addCost = async (event: React.FormEvent) => {
    event.preventDefault(); const record = data.procurementCases.find((item) => item.id === costCaseId); if (!record || !costCategory.trim() || costAmount <= 0) return;
    const cost: ProcurementCost = { id: id("cost"), date: today(), category: costCategory.trim(), description: costDescription.trim() || costCategory.trim(), amount: costAmount, currency: costCurrency.toUpperCase(), exchangeRateToBase: costCurrency.toUpperCase() === data.settings.baseCurrency.toUpperCase() ? 1 : costRate, allocation };
    if (!await onSave({ ...data, procurementCases: data.procurementCases.map((item) => item.id === record.id ? { ...item, costs: [...item.costs, cost], updatedAt: new Date().toISOString() } : item) })) return;
    setCostCategory(""); setCostDescription(""); setCostAmount(0);
  };
  const recordReceipt = async (record: ProcurementCase, lineId: string) => {
    const line = record.lines.find((item) => item.id === lineId);
    if (!line || line.receivedQuantity >= line.quantity) return;
    const raw = window.prompt(`${t.receive}: ${line.description} (${line.quantity - line.receivedQuantity} ${line.unit} remaining)`);
    if (raw === null) return;
    const receivedNow = Number(raw);
    if (!Number.isFinite(receivedNow) || receivedNow <= 0 || receivedNow > line.quantity - line.receivedQuantity) return;
    const lines = record.lines.map((item) => item.id === lineId ? { ...item, receivedQuantity: item.receivedQuantity + receivedNow } : item);
    const fullyReceived = lines.every((item) => item.receivedQuantity >= item.quantity);
    const hasReceipt = lines.some((item) => item.receivedQuantity > 0);
    const updated = { ...record, lines, status: fullyReceived ? "received" as const : hasReceipt ? "partially_received" as const : "open" as const, updatedAt: new Date().toISOString() };
    await onSave({ ...data, procurementCases: data.procurementCases.map((item) => item.id === record.id ? updated : item) });
  };
  return <div className="space-y-4">
    <Card title={t.newPurchase} icon={<PackagePlus size={16}/> }><form onSubmit={createCase} className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">
      <Field required label={t.supplier} list="company-suppliers" value={supplierName} onChange={(e) => setSupplierName(e.target.value)}/><datalist id="company-suppliers">{supplierOptions.map((item) => <option key={item.id} value={item.name}/>)}</datalist>
      <Field required label={t.number} value={caseNumber} onChange={(e) => setCaseNumber(e.target.value)}/><Field required type="date" label={t.date} value={date} onChange={(e) => setDate(e.target.value)}/><Field required label={t.currency} value={currency} onChange={(e) => setCurrency(e.target.value)}/>
      <label className="text-[11px] font-semibold text-slate-600">{t.item}<select required value={itemId} onChange={(e) => { const selected = data.items.find((item) => item.id === e.target.value); setItemId(e.target.value); if (selected) { setDescription(selected.name); setUnit(selected.unit); } }} className="mt-1 w-full rounded-lg border p-2 text-xs"><option value="">—</option>{data.items.filter((item) => item.active).map((item) => <option key={item.id} value={item.id}>{item.sku} · {item.name} ({item.unit})</option>)}</select></label><Field required label={t.description} value={description} onChange={(e) => setDescription(e.target.value)}/><Field required type="number" min="0.000001" step="any" label={t.quantity} value={quantity || ""} onChange={(e) => setQuantity(Number(e.target.value) || 0)}/>
      <label className="block text-[11px] font-semibold text-slate-600">{t.unit}<select disabled={Boolean(itemId)} value={unit} onChange={(e) => setUnit(e.target.value as typeof unit)} className="mt-1 w-full rounded-lg border p-2 text-xs disabled:bg-slate-100"><option value="mt">MT</option><option value="kg">KG</option><option value="unit">Unit</option></select></label>
      <Field required type="number" min="0" step="any" label={t.unitPrice} value={unitPrice || ""} onChange={(e) => setUnitPrice(Number(e.target.value) || 0)}/><Field required type="number" min="0" step="any" max={quantity} label={t.received} value={received || ""} onChange={(e) => setReceived(Number(e.target.value) || 0)}/>
      {currency.toUpperCase() !== data.settings.baseCurrency.toUpperCase() && <Field required type="number" min="0.000001" step="any" label={t.rate} value={rate} onChange={(e) => setRate(Number(e.target.value) || 0)}/>}
      <button disabled={saving || !data.items.some((item) => item.active)} className="inline-flex items-center justify-center gap-1 self-end rounded-lg bg-cyan-700 px-3 py-2 text-xs font-bold text-white disabled:opacity-50"><Plus size={14}/>{t.create}</button>
    </form></Card>
    {!data.items.some((item) => item.active) && <p className="rounded-lg bg-amber-50 p-3 text-xs text-amber-900">{t.noItems}</p>}
    <Card title={t.costs} icon={<Wallet size={16}/> }><form onSubmit={addCost} className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">
      <label className="text-[11px] font-semibold text-slate-600">{t.case}<select required value={costCaseId} onChange={(e) => setCostCaseId(e.target.value)} className="mt-1 w-full rounded-lg border p-2 text-xs"><option value="">—</option>{data.procurementCases.map((record) => <option key={record.id} value={record.id}>{record.number}</option>)}</select></label>
      <Field required label={t.category} value={costCategory} onChange={(e) => setCostCategory(e.target.value)}/><Field label={t.description} value={costDescription} onChange={(e) => setCostDescription(e.target.value)}/><Field required type="number" min="0.01" step="any" label={t.amount} value={costAmount || ""} onChange={(e) => setCostAmount(Number(e.target.value) || 0)}/><Field required label={t.currency} value={costCurrency} onChange={(e) => setCostCurrency(e.target.value)}/>
      <label className="text-[11px] font-semibold text-slate-600">{t.allocation}<select value={allocation} onChange={(e) => setAllocation(e.target.value as ProcurementCost["allocation"])} className="mt-1 w-full rounded-lg border p-2 text-xs"><option value="value">{t.allocationValue}</option><option value="quantity">{t.allocationQuantity}</option><option value="weight">{t.allocationWeight}</option></select></label>
      {costCurrency.toUpperCase() !== data.settings.baseCurrency.toUpperCase() && <Field required type="number" min="0.000001" step="any" label={t.rate} value={costRate} onChange={(e) => setCostRate(Number(e.target.value) || 0)}/>}
      <button disabled={saving || !data.procurementCases.length} className="self-end rounded-lg bg-indigo-700 px-3 py-2 text-xs font-bold text-white disabled:opacity-50">{t.addCost}</button>
    </form></Card>
    <Card title={t.purchaseCases}>
      {!data.procurementCases.length ? <p className="text-xs text-slate-400">{t.empty}</p> : <div className="space-y-3">{data.procurementCases.map((record) => <div key={record.id} className="overflow-x-auto rounded-lg border"><div className="flex min-w-[640px] items-center justify-between bg-slate-50 px-3 py-2 text-xs"><b>{record.number} · {data.parties.find((party) => party.id === record.supplierId)?.name}</b><span>{record.date} · {record.status}</span></div><table className="w-full min-w-[640px] text-left text-[11px]"><thead><tr className="text-slate-500"><th className="p-2">{t.item}</th><th>{t.quantity}</th><th>{t.received}</th><th>{t.currency}</th><th>{t.costPerUnit}</th><th>{t.incomplete}</th><th>{t.receive}</th></tr></thead><tbody>{record.lines.map((line) => { const cost = costing.find((item) => item.caseId === record.id && item.lineId === line.id); return <tr key={line.id} className="border-t"><td className="p-2">{line.description}</td><td>{line.quantity} {line.unit}</td><td>{line.receivedQuantity}</td><td>{line.currency}</td><td className="font-mono">{cost?.costPerUnit === null || cost?.costPerUnit === undefined ? "—" : money(cost.costPerUnit, cost.currency)}</td><td className={cost?.complete ? "text-emerald-700" : "text-amber-700"}>{cost?.complete ? t.complete : (cost?.issues[0] || t.incomplete)}</td><td>{line.receivedQuantity < line.quantity && <button type="button" disabled={saving} onClick={() => void recordReceipt(record, line.id)} className="rounded bg-cyan-50 px-2 py-1 font-bold text-cyan-800 disabled:opacity-50">{t.receive}</button>}</td></tr>; })}</tbody></table>{record.costs.length > 0 && <div className="border-t px-3 py-2 text-[10px] text-slate-500">{record.costs.map((cost) => `${cost.category}: ${money(cost.amount, cost.currency)}`).join(" · ")}</div>}</div>)}</div>}
    </Card>
  </div>;
}

function Sales({ data, t, onSave, saving, user }: { data: CompanyFinanceDatabase; t: typeof labels.en | typeof labels.tr; onSave: (next: CompanyFinanceDatabase) => Promise<boolean>; saving: boolean; user: AppUser }) {
  const [customerName, setCustomerName] = useState(""); const [number, setNumber] = useState(""); const [description, setDescription] = useState(""); const [itemId, setItemId] = useState(""); const [date, setDate] = useState(today()); const [currency, setCurrency] = useState(data.settings.baseCurrency || "USD"); const [exchangeRateToBase, setExchangeRateToBase] = useState(1); const [quantity, setQuantity] = useState(0); const [unit, setUnit] = useState<"unit" | "kg" | "mt">("mt"); const [price, setPrice] = useState(0); const [priceOverride, setPriceOverride] = useState(false); const [taxRate, setTaxRate] = useState(data.settings.taxRate || 0); const customers = data.parties.filter((party) => party.kind === "customer");
  const selectedItem = data.items.find((item) => item.id === itemId);
  const itemCost = selectedItem ? calculateWeightedAverageItemCost(data, selectedItem.id) : null;
  const priceForRate = (rate: number) => itemCost?.averageCostPerUnit === null || itemCost?.averageCostPerUnit === undefined || !selectedItem || rate <= 0 ? 0 : Number((itemCost.averageCostPerUnit * (1 + Number(selectedItem.defaultMarkupPercent || 0) / 100) / rate).toFixed(2));
  const suggestedPrice = itemCost?.averageCostPerUnit === null || itemCost?.averageCostPerUnit === undefined || !selectedItem || exchangeRateToBase <= 0 ? null : Number((itemCost.averageCostPerUnit * (1 + Number(selectedItem.defaultMarkupPercent || 0) / 100) / exchangeRateToBase).toFixed(2));
  const create = async (event: React.FormEvent) => {
    event.preventDefault(); if (!customerName.trim() || !number.trim() || !itemId || !description.trim() || quantity <= 0 || price < 0 || !selectedItem) return;
    const now = new Date().toISOString(); const customer = customers.find((item) => item.name.toLowerCase() === customerName.trim().toLowerCase()) || { id: id("customer"), kind: "customer" as const, name: customerName.trim(), createdAt: now };
    if (!data.settings.baseCurrency || (currency.toUpperCase() !== data.settings.baseCurrency.toUpperCase() && exchangeRateToBase <= 0)) return;
    const sale = { id: id("sale"), number: number.trim(), customerId: customer.id, date, currency: currency.toUpperCase(), exchangeRateToBase: currency.toUpperCase() === data.settings.baseCurrency.toUpperCase() ? 1 : exchangeRateToBase, status: "quoted" as const, lines: [{ id: id("sale-line"), itemId, description: description.trim(), quantity, unit: selectedItem.unit, unitPrice: price, taxRate, pricingMode: !priceOverride && suggestedPrice !== null ? "suggested" as const : "manual" as const, costBasisUnitPrice: itemCost?.averageCostPerUnit ?? undefined, markupPercent: selectedItem.defaultMarkupPercent ?? undefined }], createdAt: now, createdBy: user.id, updatedAt: now };
    if (!await onSave({ ...data, parties: customers.some((item) => item.id === customer.id) ? data.parties : [...data.parties, customer], localSales: [sale, ...data.localSales] })) return;
    setNumber(""); setDescription(""); setItemId(""); setQuantity(0); setPrice(0); setPriceOverride(false);
  };
  const issueInvoice = async (sale: CompanyFinanceDatabase["localSales"][number]) => {
    if (!data.settings.legalName.trim() || !data.settings.baseCurrency.trim() || !data.settings.taxConfigured) return;
    if (data.invoices.some((invoice) => invoice.localSaleId === sale.id)) return;
    const invoiceNumber = `INV-${String(data.invoices.length + 1).padStart(5, "0")}`;
    const amounts = sale.lines.reduce((total, line) => {
      const gross = line.quantity * line.unitPrice;
      const rate = line.taxRate / 100;
      if (data.settings.taxMode === "inclusive") {
        const tax = rate > 0 ? gross * rate / (1 + rate) : 0;
        return { subtotal: total.subtotal + gross - tax, tax: total.tax + tax, total: total.total + gross };
      }
      const tax = gross * rate;
      return { subtotal: total.subtotal + gross, tax: total.tax + tax, total: total.total + gross + tax };
    }, { subtotal: 0, tax: 0, total: 0 });
    const invoice = { id: id("invoice"), number: invoiceNumber, localSaleId: sale.id, issuedAt: today(), status: "issued" as const, legalNameSnapshot: data.settings.legalName, customerSnapshot: data.parties.find((party) => party.id === sale.customerId)?.name || "", currency: sale.currency, exchangeRateToBase: sale.exchangeRateToBase, taxMode: data.settings.taxMode, linesSnapshot: sale.lines.map((line) => ({ ...line })), subtotal: Number(amounts.subtotal.toFixed(2)), taxTotal: Number(amounts.tax.toFixed(2)), total: Number(amounts.total.toFixed(2)), createdAt: new Date().toISOString(), createdBy: user.id };
    await onSave({ ...data, invoices: [...data.invoices, invoice] });
  };
  return <div className="space-y-4"><Card title={t.newSale} icon={<ShoppingBag size={16}/> }><form onSubmit={create} className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">
    <Field required label={t.customer} list="company-customers" value={customerName} onChange={(e) => setCustomerName(e.target.value)}/><datalist id="company-customers">{customers.map((item) => <option key={item.id} value={item.name}/>)}</datalist>
    <Field required label={t.number} value={number} onChange={(e) => setNumber(e.target.value)}/><Field type="date" label={t.date} value={date} onChange={(e) => setDate(e.target.value)}/><Field label={t.currency} value={currency} onChange={(e) => { const next = e.target.value.toUpperCase(); setCurrency(next); const rate = next === data.settings.baseCurrency.toUpperCase() ? 1 : 0; setExchangeRateToBase(rate); setPrice(priceForRate(rate)); setPriceOverride(false); }}/>
    {currency.toUpperCase() !== data.settings.baseCurrency.toUpperCase() && <Field required type="number" min="0.000001" step="any" label={t.saleFx} value={exchangeRateToBase || ""} onChange={(e) => { const rate = Number(e.target.value) || 0; setExchangeRateToBase(rate); setPrice(priceForRate(rate)); setPriceOverride(false); }}/>}
    <label className="text-[11px] font-semibold text-slate-600">{t.item}<select required value={itemId} onChange={(e) => { const selected = data.items.find((item) => item.id === e.target.value); setItemId(e.target.value); if (selected) { setDescription(selected.name); setUnit(selected.unit); setCurrency(data.settings.baseCurrency); setExchangeRateToBase(1); setTaxRate(selected.taxRate ?? data.settings.taxRate); const cost = calculateWeightedAverageItemCost(data, selected.id); if (cost.averageCostPerUnit !== null) { const suggested = Number((cost.averageCostPerUnit * (1 + Number(selected.defaultMarkupPercent || 0) / 100)).toFixed(2)); setPrice(suggested); setPriceOverride(false); } else { setPrice(0); setPriceOverride(false); } } }} className="mt-1 w-full rounded-lg border p-2 text-xs"><option value="">—</option>{data.items.filter((item) => item.active).map((item) => <option key={item.id} value={item.id}>{item.sku} · {item.name} ({item.unit})</option>)}</select></label>
    <Field required label={t.description} value={description} onChange={(e) => setDescription(e.target.value)}/><Field required type="number" min="0.000001" step="any" label={t.quantity} value={quantity || ""} onChange={(e) => setQuantity(Number(e.target.value) || 0)}/>
    <label className="text-[11px] font-semibold text-slate-600">{t.unit}<select disabled={Boolean(itemId)} value={unit} onChange={(e) => setUnit(e.target.value as typeof unit)} className="mt-1 w-full rounded-lg border p-2 text-xs"><option value="mt">MT</option><option value="kg">KG</option><option value="unit">Unit</option></select></label>
    <Field required type="number" min="0" step="any" label={t.salePrice} value={price || ""} onChange={(e) => { setPrice(Number(e.target.value) || 0); setPriceOverride(true); }}/><Field type="number" min="0" max="100" step="any" label={t.tax} value={taxRate} onChange={(e) => setTaxRate(Number(e.target.value) || 0)}/>
    {selectedItem && <p className="self-end rounded-lg bg-slate-50 p-2 text-[10px] text-slate-600">{t.estimatedCost}: {itemCost?.averageCostPerUnit === null || itemCost?.averageCostPerUnit === undefined ? t.incomplete : money(itemCost.averageCostPerUnit, itemCost.currency)}{suggestedPrice !== null && <><br/>{t.priceHint}: {money(suggestedPrice, currency)}</>}</p>}
    <button disabled={saving || !data.items.some((item) => item.active)} className="self-end rounded-lg bg-cyan-700 px-3 py-2 text-xs font-bold text-white disabled:opacity-50">{t.createSale}</button>
  </form>{!data.items.some((item) => item.active) && <p className="mt-3 rounded-lg bg-amber-50 p-3 text-xs text-amber-900">{t.noItems}</p>}</Card>
    <Card title={t.localSales}>{!data.localSales.length ? <p className="text-xs text-slate-400">{t.empty}</p> : <div className="space-y-2">{data.localSales.map((sale) => { const invoice = data.invoices.find((item) => item.localSaleId === sale.id); return <div key={sale.id} className="flex flex-wrap items-center justify-between gap-2 rounded-lg border p-3 text-xs"><div><b className="font-mono">{sale.number}</b><span className="mx-2 text-slate-400">{sale.date}</span><span>{data.parties.find((party) => party.id === sale.customerId)?.name}</span><p className="mt-1 text-slate-500">{sale.lines[0]?.description} · {sale.lines[0]?.quantity} {sale.lines[0]?.unit} × {money(sale.lines[0]?.unitPrice || 0, sale.currency)} · {t.tax} {sale.lines[0]?.taxRate || 0}%</p></div>{invoice ? <span className="rounded bg-emerald-50 px-2 py-1 font-bold text-emerald-800">{t.invoiceNumber} {invoice.number} · {money(invoice.total, invoice.currency)}</span> : <button type="button" disabled={saving || !data.settings.legalName.trim() || !data.settings.baseCurrency.trim() || !data.settings.taxConfigured} title={!data.settings.taxConfigured ? t.invoiceReady : ""} onClick={() => void issueInvoice(sale)} className="rounded-lg bg-indigo-700 px-3 py-2 font-bold text-white disabled:opacity-40">{t.issueInvoice}</button>}</div>; })}</div>}</Card>
    <Card title={t.invoices} icon={<FileText size={16}/>}>{!data.invoices.length ? <p className="text-xs text-slate-400">{t.empty}</p> : <div className="overflow-x-auto"><table className="w-full min-w-[720px] text-left text-xs"><thead className="bg-slate-50 text-slate-500"><tr><th className="p-2">{t.invoiceNumber}</th><th>{t.date}</th><th>{t.customer}</th><th>Subtotal</th><th>Tax</th><th>{t.invoiceTotal}</th><th>Received</th><th>Balance</th><th>Status</th></tr></thead><tbody>{data.invoices.map((invoice) => { const received = data.entries.filter((entry) => entry.type === "customer_receipt" && entry.invoiceId === invoice.id && entry.paymentMethod !== "credit" && !(entry.paymentMethod === "check" && entry.checkStatus !== "cleared")).reduce((sum, entry) => sum + entry.amount, 0); return <tr key={invoice.id} className="border-t"><td className="p-2 font-mono">{invoice.number}</td><td>{invoice.issuedAt}</td><td>{invoice.customerSnapshot}</td><td>{money(invoice.subtotal, invoice.currency)}</td><td>{money(invoice.taxTotal, invoice.currency)}</td><td className="font-bold">{money(invoice.total, invoice.currency)}</td><td>{money(received, invoice.currency)}</td><td>{money(invoice.total - received, invoice.currency)}</td><td>{invoice.status}</td></tr>; })}</tbody></table></div>}</Card>
  </div>;
}

function Finance({ data, t, onSave, saving, user }: { data: CompanyFinanceDatabase; t: typeof labels.en | typeof labels.tr; onSave: (next: CompanyFinanceDatabase) => Promise<boolean>; saving: boolean; user: AppUser }) {
  const [type, setType] = useState<CompanyFinanceEntry["type"]>("company_expense"); const [date, setDate] = useState(today()); const [description, setDescription] = useState(""); const [amount, setAmount] = useState(0); const [currency, setCurrency] = useState(data.settings.baseCurrency || "USD"); const [reference, setReference] = useState(""); const [paymentMethod, setPaymentMethod] = useState<NonNullable<CompanyFinanceEntry["paymentMethod"]>>("bank"); const [checkNumber, setCheckNumber] = useState(""); const [maturity, setMaturity] = useState(""); const [bankAccountId, setBankAccountId] = useState(""); const [caseId, setCaseId] = useState(""); const [invoiceId, setInvoiceId] = useState(""); const [bankName, setBankName] = useState(""); const [bankCurrency, setBankCurrency] = useState(data.settings.baseCurrency || "USD"); const [bankOpening, setBankOpening] = useState(0); const [transferAmount, setTransferAmount] = useState(0); const [transferFrom, setTransferFrom] = useState(""); const [transferTo, setTransferTo] = useState("");
  const addEntry = async (event: React.FormEvent) => { event.preventDefault(); if (!description.trim() || amount <= 0 || (paymentMethod === "check" && (!checkNumber.trim() || !maturity)) || (paymentMethod === "bank" && !bankAccountId)) return; const entry: CompanyFinanceEntry = { id: id("entry"), date, type, amount, currency: currency.toUpperCase(), description: description.trim(), reference: reference.trim(), paymentMethod, bankAccountId: bankAccountId || undefined, caseId: caseId || undefined, invoiceId: invoiceId || undefined, checkNumber: paymentMethod === "check" ? checkNumber.trim() : undefined, checkMaturityDate: paymentMethod === "check" ? maturity : undefined, checkStatus: paymentMethod === "check" ? "pending" : undefined, createdAt: new Date().toISOString(), createdBy: user.id, ...(currency.toUpperCase() === data.settings.baseCurrency.toUpperCase() ? { exchangeRateToBase: 1 } : {}) }; if (!await onSave({ ...data, entries: [entry, ...data.entries] })) return; setDescription(""); setAmount(0); setReference(""); setCheckNumber(""); setMaturity(""); };
  const addBank = async (event: React.FormEvent) => { event.preventDefault(); if (!bankName.trim()) return; const account = { id: id("bank"), name: bankName.trim(), currency: bankCurrency.toUpperCase(), openingBalance: bankOpening, active: true, createdAt: new Date().toISOString() }; if (!await onSave({ ...data, bankAccounts: [...data.bankAccounts, account] })) return; setBankName(""); setBankOpening(0); };
  const addTransfer = async (event: React.FormEvent) => { event.preventDefault(); const from = data.bankAccounts.find((account) => account.id === transferFrom); const to = data.bankAccounts.find((account) => account.id === transferTo); if (!from || !to || from.id === to.id || from.currency !== to.currency || transferAmount <= 0) return; const entry: CompanyFinanceEntry = { id: id("transfer"), date, type: "bank_transfer", amount: transferAmount, currency: from.currency, description: `${from.name} → ${to.name}`, bankAccountId: from.id, transferBankAccountId: to.id, createdAt: new Date().toISOString(), createdBy: user.id, exchangeRateToBase: from.currency === data.settings.baseCurrency ? 1 : undefined }; if (!await onSave({ ...data, entries: [entry, ...data.entries] })) return; setTransferAmount(0); };
  const clearCheck = async (entry: CompanyFinanceEntry) => { if (entry.paymentMethod !== "check" || entry.checkStatus !== "pending") return; await onSave({ ...data, entries: data.entries.map((item) => item.id === entry.id ? { ...item, checkStatus: "cleared", clearedAt: new Date().toISOString() } : item) }); };
  return <div className="space-y-4"><Card title={t.companyEntries} icon={<Wallet size={16}/> }><form onSubmit={addEntry} className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><label className="text-[11px] font-semibold text-slate-600">{t.type}<select value={type} onChange={(e) => setType(e.target.value as CompanyFinanceEntry["type"])} className="mt-1 w-full rounded-lg border p-2 text-xs"><option value="company_expense">{t.expense}</option><option value="company_income">{t.income}</option><option value="supplier_payment">{t.supplierPayment}</option><option value="customer_receipt">{t.customerReceipt}</option></select></label><Field type="date" label={t.date} value={date} onChange={(e) => setDate(e.target.value)}/><Field required label={t.description} value={description} onChange={(e) => setDescription(e.target.value)}/><Field required type="number" min="0.01" step="any" label={t.amount} value={amount || ""} onChange={(e) => setAmount(Number(e.target.value) || 0)}/><Field label={t.currency} value={currency} onChange={(e) => setCurrency(e.target.value)}/><Field label={t.reference} value={reference} onChange={(e) => setReference(e.target.value)}/><label className="text-[11px] font-semibold text-slate-600">{t.paymentMethod}<select value={paymentMethod} onChange={(e) => setPaymentMethod(e.target.value as typeof paymentMethod)} className="mt-1 w-full rounded-lg border p-2 text-xs"><option value="cash">{t.cash}</option><option value="bank">{t.bankPayment}</option><option value="check">{t.check}</option><option value="credit">{t.credit}</option></select></label>{paymentMethod === "check" && <><Field required label={t.checkNumber} value={checkNumber} onChange={(e) => setCheckNumber(e.target.value)}/><Field required type="date" label={t.maturity} value={maturity} onChange={(e) => setMaturity(e.target.value)}/></>}{data.bankAccounts.length > 0 && <label className="text-[11px] font-semibold text-slate-600">{t.bankAccount}<select value={bankAccountId} onChange={(e) => setBankAccountId(e.target.value)} className="mt-1 w-full rounded-lg border p-2 text-xs"><option value="">—</option>{data.bankAccounts.filter((account) => account.currency === currency.toUpperCase()).map((account) => <option key={account.id} value={account.id}>{account.name}</option>)}</select></label>}{type === "supplier_payment" && data.procurementCases.length > 0 && <label className="text-[11px] font-semibold text-slate-600">{t.linkedCase}<select value={caseId} onChange={(e) => setCaseId(e.target.value)} className="mt-1 w-full rounded-lg border p-2 text-xs"><option value="">—</option>{data.procurementCases.map((record) => <option key={record.id} value={record.id}>{record.number}</option>)}</select></label>}{type === "customer_receipt" && data.invoices.length > 0 && <label className="text-[11px] font-semibold text-slate-600">{t.linkedInvoice}<select value={invoiceId} onChange={(e) => setInvoiceId(e.target.value)} className="mt-1 w-full rounded-lg border p-2 text-xs"><option value="">—</option>{data.invoices.map((invoice) => <option key={invoice.id} value={invoice.id}>{invoice.number} · {invoice.customerSnapshot}</option>)}</select></label>}<button disabled={saving} className="self-end rounded-lg bg-indigo-700 px-3 py-2 text-xs font-bold text-white">{t.addEntry}</button></form></Card>
    <Card title={t.bank} icon={<Landmark size={16}/> }><form onSubmit={addBank} className="mb-3 grid gap-2 sm:grid-cols-2 xl:grid-cols-4"><Field label={t.bankName} value={bankName} onChange={(e) => setBankName(e.target.value)}/><Field label={t.currency} value={bankCurrency} onChange={(e) => setBankCurrency(e.target.value)}/><Field type="number" step="any" label={t.openingBalance} value={bankOpening} onChange={(e) => setBankOpening(Number(e.target.value) || 0)}/><button disabled={saving} className="self-end rounded-lg bg-cyan-700 px-3 py-2 text-xs font-bold text-white">{t.createBank}</button></form>{data.bankAccounts.length ? <div className="space-y-2">{data.bankAccounts.map((account) => <div key={account.id} className="flex justify-between rounded-lg border p-3 text-xs"><b>{account.name}</b><span>{account.bankName || ""} · {account.currency} · {t.bankBalance}: {money(calculateBankBalance(account, data.entries), account.currency)}</span></div>)}</div> : <p className="text-xs text-slate-400">{t.noBank}</p>}</Card>
    {data.bankAccounts.length >= 2 && <Card title={t.bankTransfer}><form onSubmit={addTransfer} className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><label className="text-[11px] font-semibold text-slate-600">{t.bankAccount}<select required value={transferFrom} onChange={(e) => { setTransferFrom(e.target.value); setTransferTo(""); }} className="mt-1 w-full rounded-lg border p-2 text-xs"><option value="">—</option>{data.bankAccounts.map((account) => <option key={account.id} value={account.id}>{account.name} · {account.currency}</option>)}</select></label><label className="text-[11px] font-semibold text-slate-600">{t.transferTo}<select required value={transferTo} onChange={(e) => setTransferTo(e.target.value)} className="mt-1 w-full rounded-lg border p-2 text-xs"><option value="">—</option>{data.bankAccounts.filter((account) => account.id !== transferFrom && account.currency === data.bankAccounts.find((item) => item.id === transferFrom)?.currency).map((account) => <option key={account.id} value={account.id}>{account.name} · {account.currency}</option>)}</select></label><Field required type="number" min="0.01" step="any" label={t.amount} value={transferAmount || ""} onChange={(e) => setTransferAmount(Number(e.target.value) || 0)}/><button disabled={saving} className="self-end rounded-lg bg-violet-700 px-3 py-2 text-xs font-bold text-white">{t.submitTransfer}</button></form><InlineHelp><p className="mt-2 text-[10px] text-slate-500">Transfers are recorded as one internal movement and excluded from income/expense totals.</p></InlineHelp></Card>}
    <Card title={t.companyEntries}>{data.entries.length ? <div className="overflow-x-auto"><table className="w-full min-w-[760px] text-left text-xs"><thead className="bg-slate-50 text-slate-500"><tr><th className="p-2">{t.date}</th><th>{t.type}</th><th>{t.description}</th><th>{t.amount}</th><th>{t.paymentMethod}</th><th>{t.checkNumber}</th><th>{t.reference}</th><th></th></tr></thead><tbody>{data.entries.map((entry) => <tr key={entry.id} className="border-t"><td className="p-2">{entry.date}</td><td>{entry.type}</td><td>{entry.description}</td><td className="font-mono">{money(entry.amount, entry.currency)}</td><td>{entry.paymentMethod || "—"}</td><td>{entry.checkNumber ? `${entry.checkNumber} · ${entry.checkStatus === "cleared" ? t.clear : t.pending} · ${entry.checkMaturityDate}` : "—"}</td><td>{entry.reference}</td><td>{entry.paymentMethod === "check" && entry.checkStatus === "pending" && <button type="button" disabled={saving} onClick={() => void clearCheck(entry)} className="rounded bg-emerald-50 px-2 py-1 text-[10px] font-bold text-emerald-800">{t.clear}</button>}</td></tr>)}</tbody></table></div> : <p className="text-xs text-slate-400">{t.empty}</p>}</Card></div>;
}

function Settings({ data, t, onSave, saving, language }: { data: CompanyFinanceDatabase; t: typeof labels.en | typeof labels.tr; onSave: (next: CompanyFinanceDatabase) => Promise<boolean>; saving: boolean; language: CompanyLanguage }) {
  const [legalName, setLegalName] = useState(data.settings.legalName); const [baseCurrency, setBaseCurrency] = useState(data.settings.baseCurrency); const [taxRate, setTaxRate] = useState(data.settings.taxRate); const [taxMode, setTaxMode] = useState(data.settings.taxMode); const [taxConfigured, setTaxConfigured] = useState(data.settings.taxConfigured);
  const [sku, setSku] = useState(""); const [itemName, setItemName] = useState(""); const [itemNameTr, setItemNameTr] = useState(""); const [itemUnit, setItemUnit] = useState<"unit" | "kg" | "mt">("mt"); const [weightPerUnitKg, setWeightPerUnitKg] = useState(0); const [itemTaxRate, setItemTaxRate] = useState(""); const [markupPercent, setMarkupPercent] = useState(0);
  useEffect(() => { setLegalName(data.settings.legalName); setBaseCurrency(data.settings.baseCurrency); setTaxRate(data.settings.taxRate); setTaxMode(data.settings.taxMode); setTaxConfigured(data.settings.taxConfigured); }, [data]);
  const createContact = async (kind: "supplier" | "customer") => { const name = window.prompt(kind === "supplier" ? t.supplier : t.customer); if (!name?.trim()) return; const party = { id: id(kind), kind, name: name.trim(), createdAt: new Date().toISOString() } as const; await onSave({ ...data, parties: [...data.parties, party] }); };
  const createItem = async (event: React.FormEvent) => {
    event.preventDefault(); if (!sku.trim() || !itemName.trim() || data.items.some((item) => item.sku.toLowerCase() === sku.trim().toLowerCase())) return;
    const item = { id: id("item"), sku: sku.trim(), name: itemName.trim(), nameTr: itemNameTr.trim() || undefined, unit: itemUnit, weightPerUnitKg: itemUnit === "unit" && weightPerUnitKg > 0 ? weightPerUnitKg : undefined, taxRate: itemTaxRate === "" ? undefined : Number(itemTaxRate), defaultMarkupPercent: markupPercent, active: true, createdAt: new Date().toISOString() };
    if (!await onSave({ ...data, items: [...data.items, item] })) return;
    setSku(""); setItemName(""); setItemNameTr(""); setWeightPerUnitKg(0); setItemTaxRate(""); setMarkupPercent(0);
  };
  return <div className="space-y-4"><Card title={t.settings} icon={<Settings2 size={16}/> }><form onSubmit={(event) => { event.preventDefault(); void onSave({ ...data, settings: { ...data.settings, legalName: legalName.trim(), baseCurrency: baseCurrency.trim().toUpperCase(), taxRate, taxConfigured, taxMode, locale: language } }); }} className="grid gap-3 sm:grid-cols-2"><Field required label={t.legalName} value={legalName} onChange={(e) => setLegalName(e.target.value)}/><Field required label={t.baseCurrency} value={baseCurrency} onChange={(e) => setBaseCurrency(e.target.value)}/><Field type="number" min="0" max="100" step="any" label={t.defaultTax} value={taxRate} onChange={(e) => setTaxRate(Number(e.target.value) || 0)}/><label className="text-[11px] font-semibold text-slate-600">{t.taxMode}<select value={taxMode} onChange={(e) => setTaxMode(e.target.value as typeof taxMode)} className="mt-1 w-full rounded-lg border p-2 text-xs"><option value="exclusive">{t.exclusive}</option><option value="inclusive">{t.inclusive}</option></select></label><label className="flex items-center gap-2 rounded-lg border p-2 text-xs"><input type="checkbox" checked={taxConfigured} onChange={(e) => setTaxConfigured(e.target.checked)}/>{t.taxConfigured}</label><button disabled={saving} className="rounded-lg bg-cyan-700 px-3 py-2 text-xs font-bold text-white">{t.saveSettings}</button></form><InlineHelp><p className="mt-3 text-[10px] leading-5 text-slate-500">Inventory method: moving weighted average. Tax configuration is stored per company. Issued invoice snapshots retain the tax treatment used.</p></InlineHelp></Card>
    <Card title={t.addItem} icon={<PackagePlus size={16}/>}><form onSubmit={createItem} className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><Field required label={t.sku} value={sku} onChange={(e) => setSku(e.target.value)}/><Field required label={t.itemName} value={itemName} onChange={(e) => setItemName(e.target.value)}/>{language === "tr" && <Field label={t.itemNameTr} value={itemNameTr} onChange={(e) => setItemNameTr(e.target.value)}/>}<label className="text-[11px] font-semibold text-slate-600">{t.unit}<select value={itemUnit} onChange={(e) => setItemUnit(e.target.value as typeof itemUnit)} className="mt-1 w-full rounded-lg border p-2 text-xs"><option value="mt">MT</option><option value="kg">KG</option><option value="unit">Unit</option></select></label>{itemUnit === "unit" && <Field type="number" min="0.000001" step="any" label={t.weight} value={weightPerUnitKg || ""} onChange={(e) => setWeightPerUnitKg(Number(e.target.value) || 0)}/>}<Field type="number" min="0" max="100" step="any" label={t.tax} value={itemTaxRate} onChange={(e) => setItemTaxRate(e.target.value)}/><Field type="number" min="0" step="any" label={t.markup} value={markupPercent} onChange={(e) => setMarkupPercent(Number(e.target.value) || 0)}/><button disabled={saving} className="self-end rounded-lg bg-indigo-700 px-3 py-2 text-xs font-bold text-white">{t.addItem}</button></form><div className="mt-3 grid gap-2 sm:grid-cols-2">{data.items.map((item) => <div key={item.id} className="rounded-lg border p-2 text-xs"><b>{item.sku} · {item.name}</b><span className="float-right">{item.unit} · {item.defaultMarkupPercent || 0}%</span></div>)}</div></Card>
    <Card title={t.party}><div className="flex flex-wrap gap-2"><button type="button" onClick={() => void createContact("supplier")} className="rounded-lg border px-3 py-2 text-xs">+ {t.supplier}</button><button type="button" onClick={() => void createContact("customer")} className="rounded-lg border px-3 py-2 text-xs">+ {t.customer}</button></div><div className="mt-3 grid gap-2 sm:grid-cols-2">{data.parties.map((party) => <div key={party.id} className="rounded-lg border p-2 text-xs"><b>{party.name}</b><span className="float-right text-slate-500">{party.kind}</span></div>)}</div></Card></div>;
}
